    lyricScroll = $('.lscroll'); lyricBox = $('.lbox'); lyricNote = $('.lnote');
    waveEl = $('.wave'); wavePathBg = $('.w-bg'); wavePathFg = $('.w-fg'); waveDot = $('.w-dot');
    tCur = $('.t-cur'); tDur = $('.t-dur');
    volRange = $('input[type=range]'); volBtn = $('[data-act=mute]');
    chipSleep = $('[data-act=sleep]'); chipQuality = $('[data-act=quality]'); chipFav = $('.chips [data-act=favonly]'); chipDbl = $('.chips [data-act=dblclear]');
