  function shrinkImg(file, cb) {
    var fr = new FileReader();
    fr.onload = function () {
      var im = new Image();
      im.onload = function () {
        try {
          var w = im.naturalWidth, h = im.naturalHeight, m = Math.min(w, h), c = document.createElement('canvas');
          c.width = c.height = Math.min(480, m);
          c.getContext('2d').drawImage(im, (w - m) / 2, (h - m) / 2, m, m, 0, 0, c.width, c.height);
          cb(c.toDataURL('image/jpeg', 0.82));
        } catch (e) { cb(''); }
      };
      im.onerror = function () { cb(''); };
      im.src = fr.result;
    };
    fr.onerror = function () { cb(''); };
    fr.readAsDataURL(file);
  }
