    var s = cur();
    try {
      if (!s) { navigator.mediaSession.metadata = null; navigator.mediaSession.playbackState = 'none'; return; }
      var art = [];
      if (s.cover) [96, 128, 192, 256, 384, 512].forEach(function (n) { art.push({ src: absUrl(cov(s.cover, n)), sizes: n + 'x' + n, type: 'image/jpeg' }); });
      navigator.mediaSession.metadata = new MediaMetadata({ title: s.name, artist: s.artist, album: s.album || '', artwork: art });
    } catch (e) { }
