    var j = null; try { j = JSON.parse(lsGet(clSnapKey())); } catch (e) { j = null; }
    CL.snap = (j && typeof j === 'object' && j.lists) ? j : { fav: '', lists: {} };
    if (!CL.snap.lists) CL.snap.lists = {};
